-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     REPORT_DATE                                     AS \"Report Date\",     TRANSACTION_DATE                                AS \"Transaction Date\",     SOURCE_PROGRAM                                  AS \"Source Program\",     CASE SOURCE_PROGRAM             WHEN 'salesupload.ksh'                 THEN 'POS Sales Upload - tran codes 01/04/11/13/15/60'             WHEN 'trandataprocess.ksh'                 THEN 'External Tran Injection - any tran code from file'             WHEN 'dealfinc.pc'                 THEN 'Fixed Deal Income - tran code 08'             WHEN 'saldly.pc'                 THEN 'Stock Ledger Daily Rollup - TRAN_DATA to DAILY_DATA'             WHEN 'salstage.pc'                 THEN 'Stock Ledger Staging - TRAN_DATA to IF_TRAN_DATA'             WHEN 'invclshp.pc'                 THEN 'PO Receipt Processing - tran code 20'             WHEN 'rplbld.pc'                 THEN 'Replenishment Order Build - tran codes 20/31'             WHEN 'reqext.pc'                 THEN 'Replenishment Transfer Build - tran codes 30/31'             WHEN 'rtvcrt.pc'                 THEN 'RTV Creation - tran code 24'             WHEN 'wasteadj.pc'                 THEN 'Waste Adjustment - tran codes 22/23'             WHEN 'stkvar.pc'                 THEN 'Stock Variance - tran code 22'             ELSE SOURCE_PROGRAM || ' - refer batch schedule'     END                                                 AS \"Source Program Role\",      TRAN_CODE                                       AS \"Tran Code\",     CASE TRAN_CODE             WHEN 1                 THEN '01 - Net Sales'             WHEN 2                 THEN '02 - Net Sales VAT Excl'             WHEN 3                 THEN '03 - Non-Inventory Sales'             WHEN 4                 THEN '04 - Customer Returns'             WHEN 5                 THEN '05 - Non-Inventory VAT Excl'             WHEN 6                 THEN '06 - Deal Income (Sales)'             WHEN 7                 THEN '07 - Deal Income (Non-Sales)'             WHEN 8                 THEN '08 - Fixed Deal Income'             WHEN 11                 THEN '11 - Markup'             WHEN 12                 THEN '12 - Markup Cancel'             WHEN 13                 THEN '13 - Permanent Markdown'             WHEN 14                 THEN '14 - Markdown Cancel'             WHEN 15                 THEN '15 - Promotional Markdown'             WHEN 16                 THEN '16 - Clearance Markdown'             WHEN 20                 THEN '20 - Purchases'             WHEN 22                 THEN '22 - Inventory Adjustment'             WHEN 23                 THEN '23 - Inventory Adjustment COGS'             WHEN 24                 THEN '24 - Return to Vendor'             WHEN 27                 THEN '27 - Intercompany Transfer Out'             WHEN 28                 THEN '28 - Intercompany Transfer In'             WHEN 30                 THEN '30 - Transfer Out'             WHEN 31                 THEN '31 - Transfer In'             WHEN 37                 THEN '37 - GL Journal Debit'             WHEN 38                 THEN '38 - GL Journal Credit'             WHEN 60                 THEN '60 - Employee Discount'             WHEN 63                 THEN '63 - GL Manual Debit'             WHEN 64                 THEN '64 - GL Manual Credit'             WHEN 70                 THEN '70 - Cost Variance'             WHEN 80                 THEN '80 - Stock Count Adj (retail)'             WHEN 81                 THEN '81 - Stock Count Adj (cost)'             WHEN 88                 THEN '88 - VAT Sales'             ELSE 'Tran Code ' || TO_CHAR(TRAN_CODE)     END                                                 AS \"Tran Code DESC\",      DEPT_NO                                         AS \"Dept No\",     DEPT_NAME                                       AS \"Dept Name\",     ACCOUNTING_METHOD                               AS \"Accounting Method\",     CASE ACCOUNTING_METHOD             WHEN 1                 THEN 'Cost Method'             WHEN 2                 THEN 'Retail Method'     END                                                 AS \"Accounting Method DESC\",      LOC_TYPE                                        AS \"LOC Type\",     TRANSACTION_COUNT                               AS \"Transaction Count\",     ROUND(TOTAL_COST_RAW, 2)                        AS \"Total Cost\",     ROUND(TOTAL_RETAIL_RAW, 2)                      AS \"Total Retail\",     ROUND(TOTAL_UNITS_RAW, 2)                       AS \"Total Units\",     ROUND(AVG_UNIT_COST_RAW, 4)                     AS \"Avg Unit Cost\",     GL_REF_COUNT                                    AS \"GL Ref Count\",     NO_GL_REF_COUNT                                 AS \"No GL Ref Count\",     NULL_COST_COUNT                                 AS \"Null Cost Count\",     NULL_RETAIL_COUNT                               AS \"Null Retail Count\",     CASE             WHEN TRANSACTION_COUNT &gt; 0                 THEN ROUND(GL_REF_COUNT * 100.0 / TRANSACTION_COUNT, 2)     END                                                 AS \"GL Ref Coverage PCT\",      FIRST_TRAN_DATE                                 AS \"First Tran Date\",     LAST_TRAN_DATE                                  AS \"Last Tran Date\",     CASE WHEN TRAN_CODE IN (37,38,63,64) AND NO_GL_REF_COUNT &gt; 0 THEN 'FAIL: GL_REF_NO required - ' || TO_CHAR(NO_GL_REF_COUNT) || ' missing from ' || SOURCE_PROGRAM             WHEN TRAN_CODE IN (22,23) AND NULL_COST_COUNT &gt; 0                 THEN 'FAIL: TOTAL_COST required for 22/23; ' || TO_CHAR(NULL_COST_COUNT) || ' NULL from ' || SOURCE_PROGRAM             WHEN TRAN_CODE IN (11,12,13,14,15,16,60,80,81) AND NULL_RETAIL_COUNT &gt; 0                 THEN 'FAIL: TOTAL_RETAIL required; ' || TO_CHAR(NULL_RETAIL_COUNT) || ' NULL from ' || SOURCE_PROGRAM             WHEN TRAN_CODE IN (1,4,20,24,27,30,31) AND NULL_COST_COUNT &gt; 0                 THEN 'WARNING: TOTAL_COST expected; ' || TO_CHAR(NULL_COST_COUNT) || ' NULL from ' || SOURCE_PROGRAM             WHEN ROUND(TOTAL_COST_RAW, 2) = 0 AND TRANSACTION_COUNT &gt; 0 AND TRAN_CODE IN (1,4,20,22,23,24,30,31)                 THEN 'WARNING: Zero total cost from ' || SOURCE_PROGRAM             WHEN NO_GL_REF_COUNT &gt; 0                 THEN 'REVIEW: ' || TO_CHAR(NO_GL_REF_COUNT) || ' from ' || SOURCE_PROGRAM || ' missing GL_REF_NO'             ELSE 'HEALTHY'     END                                                 AS \"Interface Health\",      CASE WHEN TRAN_CODE IN (37,38,63,64) AND NO_GL_REF_COUNT &gt; 0 THEN 'Check ' || SOURCE_PROGRAM || ' for GL_REF_NO population; verify FIF_GL_CROSS_REF before fifgldn2'             WHEN TRAN_CODE IN (22,23) AND NULL_COST_COUNT &gt; 0                 THEN 'Review ' || SOURCE_PROGRAM || ' for NULL TOTAL_COST; rerun trandataprocess.ksh after correction'             WHEN ROUND(TOTAL_COST_RAW, 2) = 0 AND TRANSACTION_COUNT &gt; 0                 THEN 'Reconcile zero cost from ' || SOURCE_PROGRAM || ' with Finance; check before gl_extract.ksh runs'             WHEN NO_GL_REF_COUNT &gt; 0                 THEN 'Verify FIF_GL_CROSS_REF (CODE_TYPE=GLRT) for tran code ' || TO_CHAR(TRAN_CODE) || ' from ' || SOURCE_PROGRAM             ELSE 'No action required - ' || SOURCE_PROGRAM || ' posting is healthy'     END                                                 AS \"Recommended Action\" FROM (

