-- ── Query 3 ────────────────────────────────────────────────────────────
SELECT\\n    REPORT_DATE                                     AS \\\"Report Date\\\",\\n    TRANSACTION_DATE                                AS \\\"Transaction Date\\\",\\n    SOURCE_PROGRAM                                  AS \\\"Source Program\\\",\\n    CASE SOURCE_PROGRAM\\n            WHEN 'salesupload.ksh'\\n                THEN 'POS Sales Upload - tran codes 01/04/11/13/15/60'\\n            WHEN 'trandataprocess.ksh'\\n                THEN 'External Tran Injection - any tran code from file'\\n            WHEN 'dealfinc.pc'\\n                THEN 'Fixed Deal Income - tran code 08'\\n            WHEN 'saldly.pc'\\n                THEN 'Stock Ledger Daily Rollup - TRAN_DATA to DAILY_DATA'\\n            WHEN 'salstage.pc'\\n                THEN 'Stock Ledger Staging - TRAN_DATA to IF_TRAN_DATA'\\n            WHEN 'invclshp.pc'\\n                THEN 'PO Receipt Processing - tran code 20'\\n            WHEN 'rplbld.pc'\\n                THEN 'Replenishment Order Build - tran codes 20/31'\\n            WHEN 'reqext.pc'\\n                THEN 'Replenishment Transfer Build - tran codes 30/31'\\n            WHEN 'rtvcrt.pc'\\n                THEN 'RTV Creation - tran code 24'\\n            WHEN 'wasteadj.pc'\\n                THEN 'Waste Adjustment - tran codes 22/23'\\n            WHEN 'stkvar.pc'\\n                THEN 'Stock Variance - tran code 22'\\n            ELSE SOURCE_PROGRAM || ' - refer batch schedule'\\n    END                                                 AS \\\"Source Program Role\\\",\\n\\n    TRAN_CODE                                       AS \\\"Tran Code\\\",\\n    CASE TRAN_CODE\\n            WHEN 1\\n                THEN '01 - Net Sales'\\n            WHEN 2\\n                THEN '02 - Net Sales VAT Excl'\\n            WHEN 3\\n                THEN '03 - Non-Inventory Sales'\\n            WHEN 4\\n                THEN '04 - Customer Returns'\\n            WHEN 5\\n                THEN '05 - Non-Inventory VAT Excl'\\n            WHEN 6\\n                THEN '06 - Deal Income (Sales)'\\n            WHEN 7\\n                THEN '07 - Deal Income (Non-Sales)'\\n            WHEN 8\\n                THEN '08 - Fixed Deal Income'\\n            WHEN 11\\n                THEN '11 - Markup'\\n            WHEN 12\\n                THEN '12 - Markup Cancel'\\n            WHEN 13\\n                THEN '13 - Permanent Markdown'\\n            WHEN 14\\n                THEN '14 - Markdown Cancel'\\n            WHEN 15\\n                THEN '15 - Promotional Markdown'\\n            WHEN 16\\n                THEN '16 - Clearance Markdown'\\n            WHEN 20\\n                THEN '20 - Purchases'\\n            WHEN 22\\n                THEN '22 - Inventory Adjustment'\\n            WHEN 23\\n                THEN '23 - Inventory Adjustment COGS'\\n            WHEN 24\\n                THEN '24 - Return to Vendor'\\n            WHEN 27\\n                THEN '27 - Intercompany Transfer Out'\\n            WHEN 28\\n                THEN '28 - Intercompany Transfer In'\\n            WHEN 30\\n                THEN '30 - Transfer Out'\\n            WHEN 31\\n                THEN '31 - Transfer In'\\n            WHEN 37\\n                THEN '37 - GL Journal Debit'\\n            WHEN 38\\n                THEN '38 - GL Journal Credit'\\n            WHEN 60\\n                THEN '60 - Employee Discount'\\n            WHEN 63\\n                THEN '63 - GL Manual Debit'\\n            WHEN 64\\n                THEN '64 - GL Manual Credit'\\n            WHEN 70\\n                THEN '70 - Cost Variance'\\n            WHEN 80\\n                THEN '80 - Stock Count Adj (retail)'\\n            WHEN 81\\n                THEN '81 - Stock Count Adj (cost)'\\n            WHEN 88\\n                THEN '88 - VAT Sales'\\n            ELSE 'Tran Code ' || TO_CHAR(TRAN_CODE)\\n    END                                                 AS \\\"Tran Code DESC\\\",\\n\\n    DEPT_NO                                         AS \\\"Dept No\\\",\\n    DEPT_NAME                                       AS \\\"Dept Name\\\",\\n    ACCOUNTING_METHOD                               AS \\\"Accounting Method\\\",\\n    CASE ACCOUNTING_METHOD\\n            WHEN 1\\n                THEN 'Cost Method'\\n            WHEN 2\\n                THEN 'Retail Method'\\n    END                                                 AS \\\"Accounting Method DESC\\\",\\n\\n    LOC_TYPE                                        AS \\\"LOC Type\\\",\\n    TRANSACTION_COUNT                               AS \\\"Transaction Count\\\",\\n    ROUND(TOTAL_COST_RAW, 2)                        AS \\\"Total Cost\\\",\\n    ROUND(TOTAL_RETAIL_RAW, 2)                      AS \\\"Total Retail\\\",\\n    ROUND(TOTAL_UNITS_RAW, 2)                       AS \\\"Total Units\\\",\\n    ROUND(AVG_UNIT_COST_RAW, 4)                     AS \\\"Avg Unit Cost\\\",\\n    GL_REF_COUNT                                    AS \\\"GL Ref Count\\\",\\n    NO_GL_REF_COUNT                                 AS \\\"No GL Ref Count\\\",\\n    NULL_COST_COUNT                                 AS \\\"Null Cost Count\\\",\\n    NULL_RETAIL_COUNT                               AS \\\"Null Retail Count\\\",\\n    CASE\\n            WHEN TRANSACTION_COUNT &gt; 0\\n                THEN ROUND(GL_REF_COUNT * 100.0 / TRANSACTION_COUNT, 2)\\n    END                                                 AS \\\"GL Ref Coverage PCT\\\",\\n\\n    FIRST_TRAN_DATE                                 AS \\\"First Tran Date\\\",\\n    LAST_TRAN_DATE                                  AS \\\"Last Tran Date\\\",\\n    CASE WHEN TRAN_CODE IN (37,38,63,64) AND NO_GL_REF_COUNT &gt; 0 THEN 'FAIL: GL_REF_NO required - ' || TO_CHAR(NO_GL_REF_COUNT) || ' missing from ' || SOURCE_PROGRAM\\n            WHEN TRAN_CODE IN (22,23) AND NULL_COST_COUNT &gt; 0\\n                THEN 'FAIL: TOTAL_COST required for 22/23; ' || TO_CHAR(NULL_COST_COUNT) || ' NULL from ' || SOURCE_PROGRAM\\n            WHEN TRAN_CODE IN (11,12,13,14,15,16,60,80,81) AND NULL_RETAIL_COUNT &gt; 0\\n                THEN 'FAIL: TOTAL_RETAIL required; ' || TO_CHAR(NULL_RETAIL_COUNT) || ' NULL from ' || SOURCE_PROGRAM\\n            WHEN TRAN_CODE IN (1,4,20,24,27,30,31) AND NULL_COST_COUNT &gt; 0\\n                THEN 'WARNING: TOTAL_COST expected; ' || TO_CHAR(NULL_COST_COUNT) || ' NULL from ' || SOURCE_PROGRAM\\n            WHEN ROUND(TOTAL_COST_RAW, 2) = 0 AND TRANSACTION_COUNT &gt; 0 AND TRAN_CODE IN (1,4,20,22,23,24,30,31)\\n                THEN 'WARNING: Zero total cost from ' || SOURCE_PROGRAM\\n            WHEN NO_GL_REF_COUNT &gt; 0\\n                THEN 'REVIEW: ' || TO_CHAR(NO_GL_REF_COUNT) || ' from ' || SOURCE_PROGRAM || ' missing GL_REF_NO'\\n            ELSE 'HEALTHY'\\n    END                                                 AS \\\"Interface Health\\\",\\n\\n    CASE WHEN TRAN_CODE IN (37,38,63,64) AND NO_GL_REF_COUNT &gt; 0 THEN 'Check ' || SOURCE_PROGRAM || ' for GL_REF_NO population; verify FIF_GL_CROSS_REF before fifgldn2'\\n            WHEN TRAN_CODE IN (22,23) AND NULL_COST_COUNT &gt; 0\\n                THEN 'Review ' || SOURCE_PROGRAM || ' for NULL TOTAL_COST; rerun trandataprocess.ksh after correction'\\n            WHEN ROUND(TOTAL_COST_RAW, 2) = 0 AND TRANSACTION_COUNT &gt; 0\\n                THEN 'Reconcile zero cost from ' || SOURCE_PROGRAM || ' with Finance; check before gl_extract.ksh runs'\\n            WHEN NO_GL_REF_COUNT &gt; 0\\n                THEN 'Verify FIF_GL_CROSS_REF (CODE_TYPE=GLRT) for tran code ' || TO_CHAR(TRAN_CODE) || ' from ' || SOURCE_PROGRAM\\n            ELSE 'No action required - ' || SOURCE_PROGRAM || ' posting is healthy'\\n    END                                                 AS \\\"Recommended Action\\\"\\nFROM (\\n

-- ── Query 4 ────────────────────────────────────────────────────────────
SELECT\\n        TRUNC(SYSDATE)                                    AS REPORT_DATE,\\n        TRUNC(td.TRAN_DATE)                               AS TRANSACTION_DATE,\\n        NVL(td.PGM_NAME, 'UNKNOWN')                       AS SOURCE_PROGRAM,\\n        td.TRAN_CODE                                      AS TRAN_CODE,\\n        td.DEPT                                           AS DEPT_NO,\\n        d.DEPT_NAME                                       AS DEPT_NAME,\\n        d.PROFIT_CALC_TYPE                                AS ACCOUNTING_METHOD,\\n        td.LOC_TYPE                                       AS LOC_TYPE,\\n        COUNT(*)                                          AS TRANSACTION_COUNT,\\n        SUM(NVL(td.TOTAL_COST,   0))                      AS TOTAL_COST_RAW,\\n        SUM(NVL(td.TOTAL_RETAIL, 0))                      AS TOTAL_RETAIL_RAW,\\n        SUM(NVL(td.UNITS,        0))                      AS TOTAL_UNITS_RAW,\\n        AVG(NVL(td.AV_COST,      0))                      AS AVG_UNIT_COST_RAW,\\n        COUNT(DISTINCT td.GL_REF_NO)                      AS GL_REF_COUNT,\\n        SUM(CASE WHEN td.GL_REF_NO    IS NULL THEN 1 ELSE 0 END)\\n                                                          AS NO_GL_REF_COUNT,\\n        SUM(CASE WHEN td.TOTAL_COST   IS NULL THEN 1 ELSE 0 END)\\n                                                          AS NULL_COST_COUNT,\\n        SUM(CASE WHEN td.TOTAL_RETAIL IS NULL THEN 1 ELSE 0 END)\\n                                                          AS NULL_RETAIL_COUNT,\\n        MIN(td.TRAN_DATE)                                 AS FIRST_TRAN_DATE,\\n        MAX(td.TRAN_DATE)                                 AS LAST_TRAN_DATE\\n    FROM  MFCS_RDS.RDS_WV_TRAN_DATA            td\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                 d    ON  td.DEPT = d.DEPT\\n    WHERE\\n        td.TRAN_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n    GROUP BY\\n        TRUNC(td.TRAN_DATE),\\n        NVL(td.PGM_NAME, 'UNKNOWN'),\\n        td.TRAN_CODE,\\n        td.DEPT, d.DEPT_NAME, d.PROFIT_CALC_TYPE,\\n        td.LOC_TYPE\\n)\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-08-04T04:36:28.881+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_531_RMS_vs_GL_Trans_Control'","parent-namespace":"ReCommon","parent-name":"RPT_531_RMS_vs_GL_Trans_Control","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_531_RMS_vs_GL_Trans_Control'"}
